interface.definition:
a!localVariables(
  local!yearFilter,
  local!buFilter,
  /*local!regionFilter,*/
  local!paging: #"SYSTEM_SYSRULES_pagingInfo"( 
    startIndex: 1,
    batchSize: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3919954",
    sort: #"SYSTEM_SYSRULES_sortInfo"(field: "rotationalAskId")
  ),
  local!buRefData: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
    isActive: true,
    returnCDT: true
  ),
  local!buDropDown: local!buRefData
  /*if(*/
    /*rule!CAW_isBlank(local!regionFilter),*/
    /*local!buRefData,*/
    /*index(*/
      /*local!buRefData,*/
      /*wherecontains(*/
        /*tointeger(local!regionFilter),*/
        /*tointeger(property(local!buRefData,"regionId",null))*/
      /*),*/
      /*null*/
    /*)*/
  /*)*/
  ,
  local!fYearDropDown: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6751857"(),
  local!RotationalData: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5247626"(
    fetchTotalCount: true,
    pagingInfo: local!paging,
    fYear: if(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!yearFilter),null,local!yearFilter),
    /*regionId: if(rule!APN_isBlank(local!regionFilter),null,local!regionFilter),*/
    bu: if(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(local!buFilter),null,local!buFilter)
  ),
  local!indxOfBuSelected: wherecontains(
    local!buFilter,
    property(local!buRefData, "bu", null)
  ),
  local!selectedBus: index(local!buRefData, local!indxOfBuSelected, null),
  local!selectedBuBuId:index(local!selectedBus,"buId",null),
  local!documentId,
  local!isError: false,
  {
    #"SYSTEM_SYSRULES_cardLayout"(
      marginBelow: "STANDARD",
      style: "ACCENT",
      showBorder: false,
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          align: "RIGHT",
          value: {
            #"SYSTEM_SYSRULES_richTextIcon"(
              icon: "refresh",
              linkStyle: "STANDALONE",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!yearFilter,
                      local!buFilter,
                      /*local!regionFilter,*/
                      local!documentId
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              )
            ),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: " Clear Filters",
              style: "STRONG",
              linkStyle: "STANDALONE",
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    {
                      local!yearFilter,
                      local!buFilter,
                      /*local!regionFilter,*/
                      local!documentId
                    },
                    null
                  ),
                  a!save(local!isError, false)
                }
              )
            )
          }
        ),
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5247674"(
          fYearDropDown: local!fYearDropDown,
          buDropDown: local!buDropDown,
          yearFilter: local!yearFilter,
          /*regionFilter: local!regionFilter,*/
          buFilter: local!buFilter,
          paging: local!paging,
          documentId: local!documentId
        )
      }
    ),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_ButtonLayout"(
              secondaryButtons: {
                #"SYSTEM_SYSRULES_ButtonWidget"(
                  label: "Go Back",
                  value:ri!chooseId,
                  saveInto: {
                    a!save(ri!chooseId,1),
                    a!save(
                      {
                        local!yearFilter,
                        local!buFilter,
                        /*local!regionFilter,*/
                        local!documentId
                      },
                      null
                    )
                  }
                )
              }
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: if(
                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!RotationalData, "data",{})),
                "STANDARD",
                "#00A36C"
              ),
              link: if(
                #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(local!RotationalData, "data",{})),
                null,
                #"SYSTEM_SYSRULES_dynamicLink"(
                  saveInto: #"SYSTEM_SYSRULES_startProcess"(
                    processModel: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5163467",
                    processParameters: {
                      yearFilter:local!yearFilter,
                      rotationalBuId:local!selectedBuBuId,
                      /*rotationalRegionId:local!regionFilter,*/
                      exportType:#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3371544"
                    },
                    onSuccess: {
                      a!save(
                        local!documentId,
                        fv!processInfo.pv.NewDocument
                      ),
                      a!save(local!isError,false)
                    },
                    onError: {
                      a!save(local!isError,true),
                      a!save(local!documentId, null)
                    }
                  )
                )
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "file-excel-o"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "  Generate Excel Export",
                      style: "STRONG",
                    )
                  }
                )
              },
              shape: "SEMI_ROUNDED"
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: "#0BDA51",
              link:#"SYSTEM_SYSRULES_documentDownloadLink"(
                document: local!documentId
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      linkStyle: "STANDALONE",
                      icon: "download"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      text: " Download Excel Export",
                      style: "STRONG"
                    )
                  }
                ),
              },
              shape: "SEMI_ROUNDED"
            )
          },
          showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              marginBelow: "STANDARD",
              style: "STANDARD",
              link:#"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: a!save(local!documentId,null)
              ),
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  align: "CENTER",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      linkStyle: "STANDALONE",
                      icon: "refresh"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId),
                      text: " Reset",
                      style: "STRONG"
                    )
                  }
                ),
              },
              shape: "SEMI_ROUNDED"
            )
          },
          showWhen: #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!documentId)
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      showWhen: local!isError,
      marginBelow: "STANDARD",
      style: "ERROR",
      contents: {
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          align: "CENTER",
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
            style: "STRONG",
            text: "There was an error exporting Rotational ASK details. Please clear filters and try again.",
            color: "NEGATIVE"
          )
        )
      }
    ),
    #"SYSTEM_SYSRULES_boxLayout"(
      label: "Rotational ASK",
      style: "ACCENT",
      contents: #"SYSTEM_SYSRULES_gridField_v1"(
        label: "Rotational ASKs",
        labelPosition: "COLLAPSED",
        emptyGridMessage: "No Rotational ASK Records Found",
        data: local!RotationalData,
        pagingSaveInto: local!paging,
        refreshAlways: true,
        columns: {   
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Fiscal Year",
            sortField: "fYear",
            align: "CENTER",
            value: fv!row.fYear
          ),
          /*a!gridColumn(*/
            /*label: "Region",*/
            /*sortField: "region",*/
            /*align: "CENTER",*/
            /*value: fv!row.region*/
          /*),*/
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "BU",
            sortField: "bu",
            align: "CENTER",
            value: fv!row.bu
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Plan #",
            sortField: "quantity",
            align: "CENTER",
            value: fv!row.quantity
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Version",
            sortField: "version",
            align: "CENTER",
            value: fv!row.version
          ),
          #"SYSTEM_SYSRULES_gridColumn"(
            label: "Status",
            align: "CENTER",
            sortField: "isCompleted",
            value: fv!row.askStatus
          )
        },
        rowHeader: 1,
        spacing: "DENSE",
        borderStyle: "LIGHT",
        shadeAlternateRows: true()
      ),
      marginBelow: "STANDARD"
    )
  }
)
